1	import type { StorageProvider as StorageProviderId } from "@paperclipai/shared";
2	import type { Readable } from "node:stream";
3	
4	export interface PutObjectInput {
5	  objectKey: string;
6	  body: Buffer;
7	  contentType: string;
8	  contentLength: number;
9	}
10	
11	export interface GetObjectInput {
12	  objectKey: string;
13	}
14	
15	export interface GetObjectResult {
16	  stream: Readable;
17	  contentType?: string;
18	  contentLength?: number;
19	  etag?: string;
20	  lastModified?: Date;
21	}
22	
23	export interface HeadObjectResult {
24	  exists: boolean;
25	  contentType?: string;
26	  contentLength?: number;
27	  etag?: string;
28	  lastModified?: Date;
29	}
30	
31	export interface StorageProvider {
32	  id: StorageProviderId;
33	  putObject(input: PutObjectInput): Promise<void>;
34	  getObject(input: GetObjectInput): Promise<GetObjectResult>;
35	  headObject(input: GetObjectInput): Promise<HeadObjectResult>;
36	  deleteObject(input: GetObjectInput): Promise<void>;
37	}
38	
39	export interface PutFileInput {
40	  companyId: string;
41	  namespace: string;
42	  originalFilename: string | null;
43	  contentType: string;
44	  body: Buffer;
45	}
46	
47	export interface PutFileResult {
48	  provider: StorageProviderId;
49	  objectKey: string;
50	  contentType: string;
51	  byteSize: number;
52	  sha256: string;
53	  originalFilename: string | null;
54	}
55	
56	export interface StorageService {
57	  provider: StorageProviderId;
58	  putFile(input: PutFileInput): Promise<PutFileResult>;
59	  getObject(companyId: string, objectKey: string): Promise<GetObjectResult>;
60	  headObject(companyId: string, objectKey: string): Promise<HeadObjectResult>;
61	  deleteObject(companyId: string, objectKey: string): Promise<void>;
62	}
